def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        if new in text:
            return text
        raise SystemExit(f'{label} marker not found')
    return text.replace(old, new, 1)


# ---------------------------------------------------------------------------
# Dart bridge: a Flutter PlatformView backed by Android Media3 PlayerView.
# The Android side is generated by the V3 workflow after `flutter create`.
# ---------------------------------------------------------------------------
NATIVE.write_text(r'''import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

class NativeLivePlayerController {
  NativeLivePlayerController(int viewId)
      : _channel = MethodChannel('tvfull/media3_live_$viewId') {
    _channel.setMethodCallHandler(_handleNativeCall);
  }

  final MethodChannel _channel;
  final StreamController<Map<String, dynamic>> _events =
      StreamController<Map<String, dynamic>>.broadcast();
  bool _disposed = false;

  Stream<Map<String, dynamic>> get events => _events.stream;

  Future<dynamic> _handleNativeCall(MethodCall call) async {
    if (_disposed || call.method != 'event') return null;
    final raw = call.arguments;
    if (raw is Map) {
      _events.add(
        raw.map((key, value) => MapEntry(key.toString(), value)),
      );
    }
    return null;
  }

  Future<void> open({
    required String url,
    required Map<String, String> headers,
  }) async {
    await _channel.invokeMethod<void>('open', <String, dynamic>{
      'url': url,
      'headers': headers,
    });
  }

  Future<void> playPause() => _channel.invokeMethod<void>('playPause');

  Future<void> setVolume(double value) => _channel.invokeMethod<void>(
        'setVolume',
        <String, dynamic>{'value': value.clamp(0, 100).toDouble()},
      );

  Future<void> setResizeMode(int mode) => _channel.invokeMethod<void>(
        'setResizeMode',
        <String, dynamic>{'mode': mode},
      );

  Future<void> stop() => _channel.invokeMethod<void>('stop');

  Future<void> disposeController() async {
    if (_disposed) return;
    _disposed = true;
    _channel.setMethodCallHandler(null);
    await _events.close();
  }
}

class NativeLivePlayerSurface extends StatefulWidget {
  const NativeLivePlayerSurface({
    super.key,
    required this.onCreated,
  });

  final ValueChanged<NativeLivePlayerController> onCreated;

  @override
  State<NativeLivePlayerSurface> createState() =>
      _NativeLivePlayerSurfaceState();
}

class _NativeLivePlayerSurfaceState extends State<NativeLivePlayerSurface> {
  NativeLivePlayerController? _controller;

  @override
  void dispose() {
    final controller = _controller;
    if (controller != null) {
      unawaited(controller.disposeController());
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AndroidView(
      viewType: 'tvfull/media3_live_surface',
      onPlatformViewCreated: (viewId) {
        final controller = NativeLivePlayerController(viewId);
        _controller = controller;
        widget.onCreated(controller);
      },
    );
  }
}
''')

