native_methods = r'''
  void _onNativeLiveViewCreated(NativeLivePlayerController controller) {
    if (!mounted || !_useMedia3Live) return;
    _nativeLiveEventsSub?.cancel();
    _nativeLiveController = controller;
    _nativeLiveEventsSub = controller.events.listen(_handleNativeLiveEvent);
    unawaited(_playCurrent());
  }

  void _handleNativeLiveEvent(Map<String, dynamic> event) {
    if (!mounted || !_useMedia3Live) return;
    final type = event['type']?.toString() ?? '';
    final eventSession = event['session'];
    if (eventSession is int && eventSession != _sessionId) return;

    switch (type) {
      case 'buffering':
        setState(() {
          _isBuffering = true;
          _engineDiagnostic = 'Media3 · recibiendo buffer';
        });
        return;
      case 'ready':
        setState(() {
          _isBuffering = false;
          _reconnecting = false;
        });
        return;
      case 'isPlaying':
        final value = event['value'] == true;
        setState(() {
          _isPlaying = value;
          if (value) _isBuffering = false;
        });
        return;
      case 'firstFrame':
        _confirmMedia3LiveStarted();
        return;
      case 'videoSize':
        final width = event['width'];
        final height = event['height'];
        final fps = event['fps'];
        setState(() {
          if (width is int && width > 0) _videoWidth = width;
          if (height is int && height > 0) _videoHeight = height;
          if (fps is num && fps > 0) _videoFps = fps.toDouble();
        });
        return;
      case 'surface':
        final value = event['value']?.toString() ?? 'desconocida';
        setState(() {
          _engineDiagnostic = 'Media3 + $value · render nativo Android TV';
        });
        return;
      case 'ended':
        _scheduleMedia3LiveReconnect('Media3 recibió fin de señal');
        return;
      case 'error':
        final message = event['message']?.toString() ?? 'Error Media3';
        _handleMedia3LiveFailure(message);
        return;
    }
  }

  void _confirmMedia3LiveStarted() {
    if (!mounted || !_useMedia3Live) return;
    _connectTimeoutTimer?.cancel();
    _nativeLiveReconnectTimer?.cancel();
    _hasEverPlayed = true;
    _isPlaying = true;
    _isBuffering = false;
    _reconnecting = false;
    _retryCount = 0;
    _lastProgressAt = DateTime.now();

    int? elapsed;
    if (_startupStopwatch?.isRunning ?? false) {
      _startupStopwatch!.stop();
      elapsed = _startupStopwatch!.elapsedMilliseconds;
    }
    int? zapElapsed;
    if ((_zapStopwatch?.isRunning ?? false) && _zapSession == _sessionId) {
      _zapStopwatch!.stop();
      zapElapsed = _zapStopwatch!.elapsedMilliseconds;
      _zapSession = null;
    }

    final url = _startupUrl;
    setState(() {
      if (elapsed != null) _lastStartupMs = elapsed;
      if (zapElapsed != null) _lastZapMs = zapElapsed;
      _engineDiagnostic = 'Media3 + SurfaceView · primer frame confirmado';
    });
    if (url != null && elapsed != null) {
      unawaited(_metrics.recordStartup(url, elapsed));
      if (zapElapsed != null) unawaited(_metrics.recordZap(url, zapElapsed));
    }
  }

  Future<void> _playCurrentMedia3({
    bool isRetry = false,
    bool isZap = false,
  }) async {
    final controller = _nativeLiveController;
    if (controller == null || !mounted) return;

    final session = ++_sessionId;
    _connectTimeoutTimer?.cancel();
    _retryTimer?.cancel();
    _nativeLiveReconnectTimer?.cancel();
    _errorTitle = null;
    _errorMessage = null;
    _opening = true;
    _hasEverPlayed = false;
    _isPlaying = false;
    _isBuffering = true;
    _reconnecting = isRetry;
    _lastProgressAt = DateTime.now();
    _startupStopwatch = Stopwatch()..start();
    _startupSession = session;

    if (isZap) {
      _zapStopwatch = Stopwatch()..start();
      _zapSession = session;
    } else if (isRetry && (_zapStopwatch?.isRunning ?? false)) {
      _zapSession = session;
    }

    final channel = widget.playlist[_currentIndex];
    _startupUrl = channel.url;
    final headers = channel.resolvedHttpHeaders(_defaultUserAgent);

    if (mounted) {
      setState(() {
        _engineDiagnostic = 'Media3 + SurfaceView · abriendo señal';
      });
    }

    try {
      await controller.open(url: channel.url, headers: headers);
      if (!mounted || session != _sessionId) return;
      _opening = false;
      final timeoutSeconds = widget.settings.connectTimeoutSeconds.clamp(6, 15);
      _connectTimeoutTimer = Timer(Duration(seconds: timeoutSeconds), () {
        if (!mounted || session != _sessionId || _hasEverPlayed) return;
        _handleMedia3LiveFailure('El canal no entregó el primer frame');
      });
    } catch (error) {
      if (!mounted || session != _sessionId) return;
      _opening = false;
      _handleMedia3LiveFailure('No se pudo abrir con Media3: $error');
    }
  }

  void _handleMedia3LiveFailure(String message) {
    if (!mounted || !_useMedia3Live) return;
    _connectTimeoutTimer?.cancel();
    final hadPlayback = _hasEverPlayed;
    final session = _sessionId;
    final maxRetries = widget.settings.maxRetries.clamp(1, 3);

    if (_retryCount < maxRetries) {
      final delayMs = hadPlayback ? 250 : 500 * (1 << _retryCount);
      _retryCount++;
      setState(() {
        _isBuffering = true;
        _reconnecting = true;
        _engineDiagnostic = '$message · reintento Media3 $_retryCount/$maxRetries';
      });
      _nativeLiveReconnectTimer?.cancel();
      _nativeLiveReconnectTimer = Timer(Duration(milliseconds: delayMs), () {
        if (!mounted || session != _sessionId) return;
        unawaited(_playCurrentMedia3(isRetry: true));
      });
      return;
    }

    _startupStopwatch?.stop();
    _zapStopwatch?.stop();
    _zapSession = null;
    setState(() {
      _isBuffering = false;
      _isPlaying = false;
      _reconnecting = false;
      _errorMessage = 'Este canal no responde con el reproductor Media3.\nProbá nuevamente o elegí otro canal.';
      _engineDiagnostic = message;
    });
  }

  void _scheduleMedia3LiveReconnect(String reason) {
    if (!mounted || !_useMedia3Live) return;
    _handleMedia3LiveFailure(reason);
  }

  void _toggleMedia3LivePlayPause() {
    final controller = _nativeLiveController;
    if (controller != null) unawaited(controller.playPause());
  }

  void _setMedia3LiveVolume(double value) {
    _nativeLiveVolume = value.clamp(0, 100).toDouble();
    final controller = _nativeLiveController;
    if (controller != null) unawaited(controller.setVolume(_nativeLiveVolume));
  }

  void _setMedia3LiveFit(int mode) {
    final controller = _nativeLiveController;
    if (controller != null) unawaited(controller.setResizeMode(mode));
  }

'''
